mapper.select:
SELECT /* getMenuMngList */
FROM ( SELECT R.MENU_NUMB , R.SUBX_NUMB , R.MENU_NAME , R.MENU_URLX , R.SORT_ORDR , R.USEE_YSNO , R.USEE_YSNO_NAME , R.REGI_ADMN , R.REGI_ADMN_NAME , R.REGI_DATE , R.UPDT_ADMN , R.UPDT_ADMN_NAME , R.UPDT_DATE , ROW_NUMBER() OVER ( ORDER BY COALESCE(R.SORT_ORDR, 9999) , CAST(R.MENU_NUMB AS UNSIGNED) ) AS ROW_NUMB FROM ( SELECT FROM TM_ADMENU M WHERE M.SUBX_NUMB = #{topMenuSubxNumb}
ORDER BY COALESCE(M.SORT_ORDR, 9999) , CAST(M.MENU_NUMB AS UNSIGNED) ) R ) P WHERE P.ROW_NUMB BETWEEN #{startRow} AND #{endRow} ORDER BY P.ROW_NUMB


SELECT /* getMenuDtl */

  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}



  SELECT /* getSubMenuList */

    FROM TM_ADMENU
   WHERE MENU_NUMB = #{menuNumb}
     AND SUBX_NUMB != #{topMenuSubxNumb}
ORDER BY COALESCE(SORT_ORDR, 9999) ASC

mapper.insert:
/* setMenu */
INSERT INTO TM_ADMENU (
            MENU_NUMB
          , SUBX_NUMB
          , MENU_NAME
          , MENU_URLX
          , SORT_ORDR
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{menuNumb}
          , #{subxNumb}
          , #{menuName}
          , #{menuUrlx}
          , #{sortOrdr,jdbcType=NUMERIC}
          , #{useeYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)


/* setMenuAuth */
