          , READ_YSNO
          , WRIT_YSNO
          , DELT_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
)
SELECT A.AUTH_CODE
     , #{menuNumb}
     , #{subxNumb}
     , #{yes}
     , #{yes}
     , #{yes}
     , #{regiAdmn}
     , CURRENT_TIMESTAMP
     , #{updtAdmn}
     , CURRENT_TIMESTAMP
  FROM TM_AUTHXM A

mapper.update:
UPDATE /* uptMenu */
       TM_ADMENU
   SET MENU_NAME = #{menuName}
     , MENU_URLX = #{menuUrlx}
     , SORT_ORDR = #{sortOrdr,jdbcType=NUMERIC}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

mapper.delete:
DELETE /* delMenu */
  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

DELETE /* delMenuAuth */
  FROM TB_AUTHMN
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}
